/* components/rich-editor/rich-editor.css — the one editor's look (visual + source).
   Semantic tokens only; light and dark follow the app. */

/* ── Visual (Tiptap) ─────────────────────────────────────────────────────── */
.rich-editor-prose {
  caret-color: hsl(var(--foreground));
  word-break: break-word;
  color: hsl(var(--foreground));
  /* Typography tokens follow the app theme in light AND dark (no prose-invert dependency). */
  --tw-prose-body: hsl(var(--foreground));
  --tw-prose-headings: hsl(var(--foreground));
  --tw-prose-lead: hsl(var(--muted-foreground));
  --tw-prose-links: hsl(var(--primary));
  --tw-prose-bold: hsl(var(--foreground));
  --tw-prose-counters: hsl(var(--muted-foreground));
  --tw-prose-bullets: hsl(var(--muted-foreground));
  --tw-prose-hr: hsl(var(--border));
  --tw-prose-quotes: hsl(var(--foreground));
  --tw-prose-quote-borders: hsl(var(--border));
  --tw-prose-captions: hsl(var(--muted-foreground));
  --tw-prose-code: hsl(var(--foreground));
  --tw-prose-th-borders: hsl(var(--border));
  --tw-prose-td-borders: hsl(var(--border));
}
.rich-editor-prose > * + * { margin-top: 0.6em; }
.rich-editor-prose .rich-editor-source-block > :first-child { margin-top: 0; }
.rich-editor-prose .rich-editor-source-block + .rich-editor-source-block { margin-top: 1em; }
.rich-editor-prose p.is-editor-empty:first-child::before,
.rich-editor-prose .is-empty.is-editor-empty::before {
  content: attr(data-placeholder);
  float: left;
  height: 0;
  pointer-events: none;
  color: hsl(var(--muted-foreground));
}
.rich-editor-prose code {
  border-radius: 0.3rem;
  background: hsl(var(--muted));
  padding: 0.1em 0.35em;
  font-size: 0.88em;
}
.rich-editor-prose code::before,
.rich-editor-prose code::after { content: none; }
.rich-editor-prose a { color: hsl(var(--primary)); text-decoration: underline; cursor: text; }
.rich-editor-prose blockquote { border-left: 3px solid hsl(var(--border)); padding-left: 1em; font-style: normal; }
/* Typography's quote marks on a quote's first paragraph landed in every table cell of a quoted table (“Zone”); Preview draws none. */
.rich-editor-prose blockquote p::before,
.rich-editor-prose blockquote p::after { content: none; }
.rich-editor-prose .rich-editor-callout blockquote,
.rich-editor-prose .rich-editor-callout p { margin: 0.25em 0; }
.rich-editor-prose table { border-collapse: collapse; width: 100%; margin: 0.75em 0; }
.rich-editor-prose th,
.rich-editor-prose td { border: 1px solid hsl(var(--border)); padding: 0.35em 0.6em; vertical-align: top; }
.rich-editor-prose th { background: hsl(var(--muted) / 0.6); font-weight: 600; }
.rich-editor-prose th p,
.rich-editor-prose td p { margin: 0; }
.rich-editor-prose .selectedCell { background: hsl(var(--primary) / 0.12); }
.rich-editor-prose .ProseMirror-selectednode { outline: 2px solid hsl(var(--primary) / 0.5); outline-offset: 2px; border-radius: 6px; }
.rich-editor-prose .ProseMirror-gapcursor::after { border-top-color: hsl(var(--foreground)); }

/* GFM task items: a real checkbox drawn by a decoration */
.rich-editor-prose li.rich-editor-task-item { list-style: none; position: relative; }
.rich-editor-prose li.rich-editor-task-item > .rich-editor-task-box {
  position: absolute;
  left: -1.5em;
  top: 0.35em;
  width: 1rem;
  height: 1rem;
  accent-color: hsl(var(--primary));
  cursor: pointer;
}
.rich-editor-prose li.rich-editor-task-item.is-checked > p {
  color: hsl(var(--muted-foreground));
  text-decoration: line-through;
  text-decoration-color: hsl(var(--muted-foreground) / 0.6);
}

/* Footnotes */
.rich-editor-prose .rich-editor-footnote-ref {
  font-size: 0.72em;
  vertical-align: super;
  color: hsl(var(--primary));
  font-weight: 600;
}
.rich-editor-prose .rich-editor-footnote-def { color: hsl(var(--muted-foreground)); font-weight: 600; }

/* Find & replace */
.rich-editor-find-match { background: hsl(48 96% 60% / 0.45); border-radius: 2px; }
.rich-editor-find-current { background: hsl(24 95% 55% / 0.65); border-radius: 2px; }

/* Heading anchors land below the sticky chrome */
.rich-editor-prose [data-heading-slug] { scroll-margin-top: 4rem; }

/* Focus mode: everything but the block you are in fades */
.rich-editor-focus .rich-editor-prose > * { transition: opacity 180ms ease; opacity: 0.28; }
.rich-editor-focus .rich-editor-prose > .has-focus,
.rich-editor-focus .rich-editor-prose > *:has(.has-focus) { opacity: 1; }
.rich-editor-focus .cm-line { transition: opacity 180ms ease; opacity: 0.35; }
.rich-editor-focus .cm-activeLine { opacity: 1; }

/* ── Source (CodeMirror live preview) ────────────────────────────────────── */
.rich-editor-source .cm-editor { min-height: 60dvh; }
.rich-editor-source .cm-content { padding: 24px 0; }
.rich-editor-source .cm-line { padding: 0 32px; }
@media (max-width: 639px) {
  .rich-editor-source .cm-line { padding: 0 16px; }
}
.cm-rich-mark { color: hsl(var(--muted-foreground) / 0.7); }
.cm-rich-h1 { font-size: 1.6em; font-weight: 700; line-height: 1.3; }
.cm-rich-h2 { font-size: 1.35em; font-weight: 700; line-height: 1.35; }
.cm-rich-h3 { font-size: 1.15em; font-weight: 650; }
.cm-rich-h4, .cm-rich-h5, .cm-rich-h6 { font-weight: 650; }
.cm-rich-quote { border-left: 3px solid hsl(var(--border)); color: hsl(var(--muted-foreground)); }
.cm-rich-island-line { background: hsl(var(--muted) / 0.45); font-family: var(--font-mono, ui-monospace, monospace); font-size: 0.85em; }
.cm-rich-island {
  margin: 6px 32px;
  border: 1px solid hsl(var(--border));
  border-radius: 8px;
  background: hsl(var(--card) / 0.6);
  padding: 6px 12px;
  cursor: text;
  overflow: auto;
  max-height: 32rem;
}
.cm-rich-island:hover { border-color: hsl(var(--primary) / 0.5); }
.cm-rich-var { border-radius: 5px; padding: 0 2px; border: 1px solid; font-weight: 500; }
.cm-rich-var-declared { background: hsl(142 70% 45% / 0.14); color: hsl(142 60% 32%); border-color: hsl(142 60% 45% / 0.35); }
.cm-rich-var-undeclared { background: hsl(0 80% 60% / 0.14); color: hsl(0 70% 45%); border-color: hsl(0 70% 55% / 0.35); }
.cm-rich-var-literal { background: hsl(var(--muted)); color: hsl(var(--muted-foreground)); border-color: hsl(var(--border)); }
.cm-rich-var-unbound { background: hsl(var(--primary) / 0.1); color: hsl(var(--primary)); border-color: hsl(var(--primary) / 0.3); }
.dark .cm-rich-var-declared { color: hsl(142 60% 70%); }
.dark .cm-rich-var-undeclared { color: hsl(0 80% 75%); }
.cm-rich-find { background: hsl(48 96% 60% / 0.45); }
.cm-rich-find-current { background: hsl(24 95% 55% / 0.65); }

/* A code fence inside the editor already has ONE frame — the island's, with its
   language picker, copy, edit and remove. The shared renderer's own snippet
   frame and "bash" header inside it were a box in a box with the language
   named twice (page-pass /notes, 2026-09-27): inside an island the snippet is
   bare code. */
.rich-editor-island[data-island-type="fence"] .rich-editor-island-render [data-code-snippet] {
  margin: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}
.rich-editor-island[data-island-type="fence"] .rich-editor-island-render [data-code-snippet-header] {
  display: none;
}

.rich-editor-visual .ProseMirror .placeholder {
  color: hsl(var(--muted-foreground));
}

/* ONE TYPOGRAPHY for a document, written or read (page-pass /notes,
   2026-09-28): headings and lists in the editor match the shared renderer
   (components/rich-content/prose/prose-block-elements.tsx — h1 text-xl bold,
   h2 text-lg semibold, h3 text-base semibold, all blue-500 in the heading
   font; lists pl-6, mb-3, relaxed, no gap between items). */
.rich-editor-prose h1,
.rich-editor-prose h2,
.rich-editor-prose h3 {
  font-family: var(--font-heading);
  color: var(--color-blue-500);
  line-height: 1.4;
}
.rich-editor-prose h1 { font-size: 1.25rem; font-weight: 700; margin: 1rem 0 0.5rem; }
.rich-editor-prose h2 { font-size: 1.125rem; font-weight: 600; margin: 0.75rem 0 0.375rem; }
.rich-editor-prose h3 { font-size: 1rem; font-weight: 600; margin: 0.5rem 0 0.25rem; }
.rich-editor-prose > h1:first-child,
.rich-editor-prose > h2:first-child { margin-top: 0; }
.rich-editor-prose ul,
.rich-editor-prose ol { padding-left: 1.5rem; margin: 0 0 0.75rem; line-height: 1.625; }
.rich-editor-prose li { margin: 0; }
.rich-editor-prose li p { margin: 0; }

/* Inside that one frame the code itself sits flat — no second rounded band. */
.rich-editor-island[data-island-type="fence"] .rich-editor-island-render [data-code-snippet] pre,
.rich-editor-island[data-island-type="fence"] .rich-editor-island-render [data-code-snippet] code {
  background: transparent;
}
