export {
  CODE_LANGUAGES,
  MATRX_FENCE_LANGUAGE,
  fenceLanguage,
  inlineIslandLabel,
  isMatrxFence,
  islandMeta,
  kindOf,
  texOf,
  withFenceLanguage
};
