import { Extension, Mark, Node, mergeAttributes } from "@tiptap/core";
import { Document } from "@tiptap/extension-document";
import { Text } from "@tiptap/extension-text";
import { Paragraph } from "@tiptap/extension-paragraph";
import { Heading } from "@tiptap/extension-heading";
import { Bold } from "@tiptap/extension-bold";
import { Italic } from "@tiptap/extension-italic";
import { Strike } from "@tiptap/extension-strike";
import { Code } from "@tiptap/extension-code";
import { Link } from "@tiptap/extension-link";
import { Blockquote } from "@tiptap/extension-blockquote";
import { HorizontalRule } from "@tiptap/extension-horizontal-rule";
import { HardBreak } from "@tiptap/extension-hard-break";
import {
  BulletList,
  ListItem,
  ListKeymap,
  OrderedList
} from "@tiptap/extension-list";
import { Table, TableCell, TableHeader, TableRow } from "@tiptap/extension-table";
import { Dropcursor, Focus, Gapcursor, Placeholder, UndoRedo } from "@tiptap/extensions";
import { MarkdownTextPaste } from "./paste-markdown.js";
import { ClipboardPlainText } from "./clipboard-text.js";
import { MarkdownTypingRules } from "./typing-rules.js";
const mdAttr = () => ({ default: null, rendered: false, keepOnSplit: false });
const MD_ID_NODE_TYPES = [
  "paragraph",
  "heading",
  "bulletList",
  "orderedList",
  "listItem",
  "blockquote",
  "horizontalRule",
  "sourceLocked"
];
function fenceFromPre(element) {
  const code = element.querySelector("code");
  const language = /(?:^|\s)(?:language|lang)-([\w+#.-]+)/.exec(code?.className ?? element.className)?.[1] ?? "";
  const text = (code ?? element).textContent?.replace(/\n$/, "") ?? "";
  let longest = 0;
  for (const run of text.match(/`+/g) ?? []) longest = Math.max(longest, run.length);
  const fence = "`".repeat(Math.max(3, longest + 1));
  return `${fence}${language}
${text}
${fence}`;
}
const SourceBlockNode = Node.create({
  name: "sourceBlock",
  group: "topblock",
  content: "block+",
  addAttributes() {
    return { b: mdAttr() };
  },
  parseHTML() {
    return [{ tag: "div[data-md-source-block]" }];
  },
  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(HTMLAttributes, {
        "data-md-source-block": "",
        class: "rich-editor-source-block"
      }),
      0
    ];
  }
});
const IslandBlockNode = Node.create({
  name: "islandBlock",
  group: "topblock block",
  atom: true,
  selectable: true,
  draggable: true,
  addAttributes() {
    return {
      raw: { default: "", rendered: false },
      islandType: { default: "fence", rendered: false },
      complete: { default: true, rendered: false },
      b: mdAttr()
    };
  },
  parseHTML() {
    return [
      {
        tag: "div[data-md-island]",
        getAttrs: (element) => ({
          raw: element.getAttribute("data-md-raw") ?? "",
          islandType: element.getAttribute("data-md-island") ?? "fence"
        })
      },
      {
        // Pasted code (<pre>, <pre><code class="language-x">) becomes a fence island.
        tag: "pre",
        preserveWhitespace: "full",
        getAttrs: (element) => ({ raw: fenceFromPre(element), islandType: "fence" })
      }
    ];
  },
  renderHTML({ node }) {
    return [
      "div",
      {
        "data-md-island": String(node.attrs.islandType),
        "data-md-raw": String(node.attrs.raw)
      },
      ["pre", String(node.attrs.raw)]
    ];
  },
  renderText({ node }) {
    return String(node.attrs.raw);
  }
});
const SourceLockedNode = Node.create({
  name: "sourceLocked",
  group: "block",
  atom: true,
  selectable: true,
  draggable: true,
  addAttributes() {
    return {
      raw: { default: "", rendered: false },
      reason: { default: null, rendered: false },
      b: mdAttr()
    };
  },
  parseHTML() {
    return [
      {
        tag: "div[data-md-locked]",
        getAttrs: (element) => ({
          raw: element.getAttribute("data-md-raw") ?? ""
        })
      }
    ];
  },
  renderHTML({ node }) {
    return [
      "div",
      { "data-md-locked": "", "data-md-raw": String(node.attrs.raw) },
      ["pre", String(node.attrs.raw)]
    ];
  },
  renderText({ node }) {
    return String(node.attrs.raw);
  }
});
const InlineIslandNode = Node.create({
  name: "inlineIsland",
  group: "inline",
  inline: true,
  atom: true,
  selectable: true,
  addAttributes() {
    return {
      raw: { default: "", rendered: false },
      islandType: { default: "variable", rendered: false }
    };
  },
  parseHTML() {
    return [
      {
        // Pasted images keep their bytes as a markdown image island.
        tag: "img[src]",
        getAttrs: (element) => ({
          raw: `![${(element.getAttribute("alt") ?? "").replace(/[[\]]/g, "")}](${element.getAttribute("src") ?? ""})`,
          islandType: "md_image"
        })
      },
      {
        tag: "span[data-md-inline]",
        getAttrs: (element) => ({
          raw: element.getAttribute("data-md-raw") ?? "",
          islandType: element.getAttribute("data-md-inline") ?? "variable"
        })
      }
    ];
  },
  renderHTML({ node }) {
    return [
      "span",
      {
        "data-md-inline": String(node.attrs.islandType),
        "data-md-raw": String(node.attrs.raw)
      },
      String(node.attrs.raw)
    ];
  },
  renderText({ node }) {
    return String(node.attrs.raw);
  }
});
const MarkdownFidelityAttributes = Extension.create({
  name: "markdownFidelity",
  addGlobalAttributes() {
    return [
      { types: [...MD_ID_NODE_TYPES], attributes: { mdId: mdAttr() } },
      { types: ["heading"], attributes: { mdOpen: mdAttr(), mdClose: mdAttr() } },
      {
        types: ["listItem"],
        attributes: {
          mdLead: mdAttr(),
          mdMarker: mdAttr(),
          mdAfter: mdAttr(),
          mdTask: mdAttr(),
          mdIndent: mdAttr()
        }
      },
      { types: ["blockquote"], attributes: { mdPrefix: mdAttr(), mdAlert: mdAttr() } },
      {
        types: ["table"],
        attributes: { mdId: mdAttr(), mdDelim: mdAttr(), mdAligns: mdAttr(), mdPipes: mdAttr() }
      },
      { types: ["tableRow"], attributes: { mdRaw: mdAttr(), mdCells: mdAttr(), mdSegs: mdAttr() } },
      { types: ["horizontalRule", "hardBreak"], attributes: { mdRaw: mdAttr() } },
      {
        types: ["bold", "italic", "strike"],
        attributes: { mdMarker: mdAttr(), mdDepth: mdAttr() }
      },
      {
        types: ["code"],
        attributes: { mdOpen: mdAttr(), mdClose: mdAttr(), mdDepth: mdAttr() }
      },
      {
        types: ["link"],
        attributes: {
          mdForm: mdAttr(),
          mdTail: mdAttr(),
          mdTailHref: mdAttr(),
          mdText: mdAttr(),
          mdDepth: mdAttr()
        }
      }
    ];
  }
});
const NewlineHardBreak = HardBreak.extend({
  addKeyboardShortcuts() {
    const newline = () => this.editor.commands.command(({ tr, dispatch }) => {
      if (dispatch) tr.insertText("\n");
      return true;
    });
    return { "Shift-Enter": newline, "Mod-Enter": newline };
  }
});
const cellAlign = {
  align: {
    default: null,
    parseHTML: (element) => element.style.textAlign || null,
    renderHTML: (attributes) => attributes.align ? { style: `text-align: ${String(attributes.align)}` } : {}
  }
};
const InlineTableCell = TableCell.extend({
  content: "paragraph",
  addAttributes() {
    return { ...this.parent?.(), ...cellAlign };
  }
});
const InlineTableHeader = TableHeader.extend({
  content: "paragraph",
  addAttributes() {
    return { ...this.parent?.(), ...cellAlign };
  }
});
const CombinableCode = Code.extend({ excludes: "" });
const EscapedText = Mark.create({
  name: "mdEscape",
  inclusive: false,
  excludes: "",
  parseHTML() {
    return [{ tag: "span[data-md-escape]" }];
  },
  renderHTML() {
    return ["span", { "data-md-escape": "" }, 0];
  }
});
function createRichEditorExtensions(options = {}) {
  const list = [
    Document.extend({ content: "(block | topblock)+" }),
    Paragraph,
    Text,
    Heading.configure({ levels: [1, 2, 3, 4, 5, 6] }),
    Blockquote,
    BulletList,
    OrderedList,
    ListItem,
    ListKeymap,
    HorizontalRule,
    NewlineHardBreak,
    Bold,
    Italic,
    Strike,
    CombinableCode,
    EscapedText,
    Link.configure({
      openOnClick: false,
      autolink: false,
      linkOnPaste: true
    }),
    Table.configure({ resizable: false }),
    TableRow,
    InlineTableHeader,
    InlineTableCell,
    SourceBlockNode,
    IslandBlockNode,
    SourceLockedNode,
    InlineIslandNode,
    MarkdownFidelityAttributes,
    UndoRedo,
    Focus.configure({ className: "has-focus", mode: "shallowest" }),
    Gapcursor,
    Dropcursor,
    Placeholder.configure({ placeholder: options.placeholder ?? "Write\u2026" }),
    MarkdownTextPaste.configure({ onNotice: options.onPasteNotice ?? null }),
    ClipboardPlainText,
    MarkdownTypingRules
  ];
  return list.map((extension) => extension.extend({ addPasteRules: () => [] }));
}
export {
  EscapedText,
  InlineIslandNode,
  IslandBlockNode,
  MD_ID_NODE_TYPES,
  MarkdownFidelityAttributes,
  SourceBlockNode,
  SourceLockedNode,
  createRichEditorExtensions
};
